def build_agent(sandbox):
    # Chassis positioned to ensure ground contact and within build zone
    chassis = sandbox.add_beam(x=7.0, y=1.6, width=2.0, height=0.2, density=1.0)
    sandbox.set_fixed_rotation(chassis, True)

    # Wheels with sufficient radius to stay on ground and within build zone
    wheel_radius = 0.5
    for x_off in [-1.0, 1.0]:  # Wider wheelbase for stability
        w = sandbox.add_wheel(x=7.0 + x_off, y=1.5, radius=wheel_radius, density=1.0)
        sandbox.set_material_properties(w, friction=0.8)  # Moderate friction for traction
        joint = sandbox.add_joint(chassis, w, (7.0 + x_off, 1.5), type='pivot', lower_limit=-math.pi, upper_limit=math.pi)
        sandbox.set_motor(joint, motor_speed=3.0, max_torque=100.0)
    return chassis

def agent_action(sandbox, agent_body, step_count):
    obj_pos = sandbox.get_object_position()
    # Ensure pusher is within 1.0m of object to maintain contact
    if obj_pos[0] - agent_body.position.x > 1.0:
        # Pusher is behind object, maintain forward motion
        for joint in sandbox.get_joints_by_type('pivot'):
            sandbox.set_motor(joint, motor_speed=3.0, max_torque=100.0)
    else:
        # Object is in contact, maintain effective push
        obj_vel = (obj_pos[0] - sandbox.get_object_position()[0], 0.0)  # Simplified velocity estimate
        if obj_vel[0] < 0.05:
            # Object not moving, increase motor speed
            for joint in sandbox.get_joints_by_type('pivot'):
                sandbox.set_motor(joint, motor_speed=4.5, max_torque=100.0)
        else:
            # Maintain base motor speed
            for joint in sandbox.get_joints_by_type('pivot'):
                sandbox.set_motor(joint, motor_speed=3.0, max_torque=100.0)
